prompt:
Author one complete WGSL compute shader from the supplied contract.
Return only the complete WGSL source; no Markdown fence, diff, or explanation.
The shader must implement every binding, entry-point, dispatch, bounds, and arithmetic requirement exactly.
<task_id>channel-gain-v1-selection-gain-cubic</task_id>
<specification>
For each logical element i, let x=left_values[i] and y=right_values[i]. Return the cube of x, (x*x)*x. Follow the interface and guard out-of-range invocations.
</specification>
<interface_contract>
{
  "entryPoint": "main",
  "requiredOverrides": [
    {
      "name": "WORKGROUP_SIZE",
      "type": "u32"
    }
  ],
  "bindings": [
    {
      "group": 0,
      "binding": 0,
      "name": "left_values",
      "kind": "read_only_storage",
      "wgslType": "array<f32>"
    },
    {
      "group": 0,
      "binding": 1,
      "name": "right_values",
      "kind": "read_only_storage",
      "wgslType": "array<f32>"
    },
    {
      "group": 0,
      "binding": 2,
      "name": "output_values",
      "kind": "read_write_storage",
      "wgslType": "array<f32>"
    },
    {
      "group": 0,
      "binding": 3,
      "name": "params",
      "kind": "uniform",
      "wgslType": "Params",
      "fields": [
        {
          "name": "length",
          "type": "u32",
          "byteOffset": 0
        },
        {
          "name": "output_offset",
          "type": "u32",
          "byteOffset": 4
        },
        {
          "name": "first",
          "type": "f32",
          "byteOffset": 8
        },
        {
          "name": "second",
          "type": "f32",
          "byteOffset": 12
        }
      ]
    }
  ],
  "dispatch": "One logical element per global_invocation_id.x. Guard i>=params.length. Store only output_values[params.output_offset+i]. Preserve all input buffers and output padding."
}
</interface_contract>

